  "inlineSchema": "// Snapa — Database schema (Awamu 1: users, posts, likes, comments, follows)\n// Baadaye: stories, reels, messages, notifications (angalia blueprint)\n\ngenerator client {\n  provider = \"prisma-client-js\"\n}\n\ndatasource db {\n  provider = \"postgresql\"\n  url      = env(\"DATABASE_URL\")\n}\n\nmodel User {\n  id           String   @id @default(uuid())\n  username     String   @unique\n  email        String   @unique\n  passwordHash String\n  bio          String?\n  avatarUrl    String?\n  createdAt    DateTime @default(now())\n\n  posts    Post[]\n  likes    Like[]\n  comments Comment[]\n\n  followers Follow[] @relation(\"following\")\n  following Follow[] @relation(\"follower\")\n\n  notifications     Notification[] @relation(\"notifUser\")\n  notificationsSent Notification[] @relation(\"notifActor\")\n\n  stories          Story[]\n  sentMessages     Message[] @relation(\"sentMessages\")\n  receivedMessages Message[] @relation(\"receivedMessages\")\n\n  reels     Reel[]\n  reelLikes ReelLike[]\n  pushToken String?\n}\n\nmodel Post {\n  id        String   @id @default(uuid())\n  userId    String\n  user      User     @relation(fields: [userId], references: [id])\n  mediaUrl  String\n  caption   String?\n  hashtags  String?\n  createdAt DateTime @default(now())\n\n  likes    Like[]\n  comments Comment[]\n}\n\nmodel Like {\n  id     String @id @default(uuid())\n  userId String\n  postId String\n  user   User   @relation(fields: [userId], references: [id])\n  post   Post   @relation(fields: [postId], references: [id])\n\n  @@unique([userId, postId])\n}\n\nmodel Comment {\n  id        String   @id @default(uuid())\n  userId    String\n  postId    String\n  text      String\n  createdAt DateTime @default(now())\n  user      User     @relation(fields: [userId], references: [id])\n  post      Post     @relation(fields: [postId], references: [id])\n}\n\nmodel Follow {\n  followerId  String\n  followingId String\n  follower    User   @relation(\"follower\", fields: [followerId], references: [id])\n  following   User   @relation(\"following\", fields: [followingId], references: [id])\n\n  @@id([followerId, followingId])\n}\n\nmodel Notification {\n  id        String   @id @default(uuid())\n  userId    String // anayepokea arifa\n  actorId   String // aliyefanya kitendo\n  type      String // \"like\" | \"comment\" | \"follow\"\n  postId    String?\n  read      Boolean  @default(false)\n  createdAt DateTime @default(now())\n\n  user  User @relation(\"notifUser\", fields: [userId], references: [id])\n  actor User @relation(\"notifActor\", fields: [actorId], references: [id])\n}\n\nmodel Story {\n  id        String   @id @default(uuid())\n  userId    String\n  mediaUrl  String\n  createdAt DateTime @default(now())\n  expiresAt DateTime\n\n  user User @relation(fields: [userId], references: [id])\n}\n\nmodel Message {\n  id         String    @id @default(uuid())\n  senderId   String\n  receiverId String\n  text       String?\n  mediaUrl   String?\n  sentAt     DateTime  @default(now())\n  readAt     DateTime?\n\n  sender   User @relation(\"sentMessages\", fields: [senderId], references: [id])\n  receiver User @relation(\"receivedMessages\", fields: [receiverId], references: [id])\n}\n\nmodel Reel {\n  id        String   @id @default(uuid())\n  userId    String\n  videoUrl  String\n  caption   String?\n  createdAt DateTime @default(now())\n\n  user  User       @relation(fields: [userId], references: [id])\n  likes ReelLike[]\n}\n\nmodel ReelLike {\n  id     String @id @default(uuid())\n  userId String\n  reelId String\n  user   User   @relation(fields: [userId], references: [id])\n  reel   Reel   @relation(fields: [reelId], references: [id])\n\n  @@unique([userId, reelId])\n}\n",
